set -euo pipefail
export PATH="/home/briansrls/.cargo/bin:$PATH"
instrument_head=a375db950e47f27daa8f623cfd025cf0b0b20c84
instrument_root=$(mktemp -d /home/briansrls/royal-hawk-241/instrument.XXXXXX)
printf '%s\n' "$instrument_root/instrument.log"
git clone --no-checkout https://github.com/gunb-ai/gunbc.git "$instrument_root/repo"
base64 -d > "$instrument_root/subject.bundle" <<'A_BUNDLE'

A_BUNDLE
git -C "$instrument_root/repo" fetch "$instrument_root/subject.bundle" HEAD
git -C "$instrument_root/repo" checkout --detach "$instrument_head"
mkdir "$instrument_root/runner-temp"
cd "$instrument_root/repo"
systemd-run --user --scope -p MemoryMax=24G env PATH="$PATH" RUNNER_TEMP="$instrument_root/runner-temp" GITHUB_SHA="$instrument_head" CTRL_BUILD_MODE=local bash -c '
set -euo pipefail
cargo build --release --bin claim_executor
./target/release/claim_executor --regen-round-cost --source-root dag --source-root src/v2
./target/release/claim_executor --required-regen-fixed-point --source-root dag --source-root src/v2
cargo test --release -p v1-compiler-tests --lib native_driver_cost
cargo build --release --bin gunbc
failed=0
for witness in validated_subject_index_matches_general_lookup keyed_validation_preserves_general_ambiguity_diagnostic validate_module_roots_malformed_root_is_rejected resolve_module_not_found_preserves_missing_module_identity shared_context_duplicate_root_refusal_preserves_every_diagnostic_for_each_subject shared_context_malformed_root_refusal_preserves_every_diagnostic_for_each_subject shared_context_resolves_two_subjects_and_preserves_missing_subject_location resolve_dual_imports_do_not_collide_on_header_metadata resolve_with_admission_threads_validate_diagnostics_on_accept; do
  if env PATH="$PATH" RUNNER_TEMP="$(mktemp -d "$RUNNER_TEMP/witness.XXXXXX")" ./target/release/gunbc run --source-root dag --source-root src/v2 --entry src/v2/test/claim/name_resolve/admission_fail_closed_test.dag --function "$witness" --claim-run; then
    printf "VERIFY %s PASS\n" "$witness"
  else
    result=$?
    printf "VERIFY %s FAIL rc=%s\n" "$witness" "$result"
    failed=1
  fi
done
for witness in shared_root_validation_refusal_stays_at_prepare_for_each_identity the_requested_declaration_is_selected_and_evaluated a_nested_same_named_graft_edge_is_not_selected an_absent_declaration_is_not_found a_sibling_modules_declaration_is_not_selected; do
  if env PATH="$PATH" RUNNER_TEMP="$(mktemp -d "$RUNNER_TEMP/witness.XXXXXX")" ./target/release/gunbc run --source-root dag --source-root src/v2 --entry src/v2/test/native_decl_selection_test.dag --function "$witness" --claim-run; then
    printf "VERIFY %s PASS\n" "$witness"
  else
    result=$?
    printf "VERIFY %s FAIL rc=%s\n" "$witness" "$result"
    failed=1
  fi
done
test "$failed" -eq 0
' > "$instrument_root/instrument.log" 2>&1 && instrument_status=0 || instrument_status=$?
git diff --binary > "$instrument_root/generated.patch"
git status --short > "$instrument_root/generated-status.txt"
printf 'INSTRUMENT_DONE rc=%s root=%s\n' "$instrument_status" "$instrument_root"
exit "$instrument_status"
